  function csv(name,headers,rows){const content='\uFEFF'+[headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV fictício exportado.');}
  function filteredClasses(){const f=state.filters;return data.classes.filter(a=>(!f.search||`${a.type} ${a.clientIds.map(clientName).join(' ')} ${instructorName(a.instructor)}`.toLocaleLowerCase('pt-BR').includes(f.search.toLocaleLowerCase('pt-BR')))&&(!f.client||a.clientIds.includes(f.client))&&(!f.recurrence||f.recurrence===(a.series?'yes':'no'))&&(!f.status||a.status===f.status)&&(!f.fromDate||a.date>=f.fromDate)&&(!f.finance||(f.finance==='due'?['pending','partial'].includes(classFinancial(a,f.client)):classFinancial(a,f.client)===f.finance))).sort((a,b)=>classSort(b,a))}
