  function table(headers,body,foot=''){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}"><div class="empty"><strong>Nenhum resultado neste recorte</strong>Ajuste os filtros para ver outros registros fictícios.</div></td></tr>`}</tbody></table></div>${foot?`<div class="table-foot">${foot}</div>`:''}`}
